window.CE_DATA={"G":{"a1":{"d":1,"phrase":"I've been working with... for...","pt":"Trabalho com... há...","when":"ao dizer sua experiência e duração","ex":"I've been working with Go for several years."},"a2":{"d":1,"phrase":"I'm responsible for...","pt":"Sou responsável por...","when":"ao explicar suas atribuições","ex":"I'm responsible for designing scalable APIs."},"a3":{"d":1,"phrase":"I tend to...","pt":"Costumo...","when":"ao falar de hábitos ou tendências","ex":"I tend to focus on reliability first."},"a4":{"d":1,"phrase":"I'm looking to...","pt":"Estou buscando...","when":"ao comentar um objetivo","ex":"I'm looking to work with an international team."},"a5":{"d":1,"phrase":"What I mean is...","pt":"O que quero dizer é...","when":"ao reformular uma ideia","ex":"What I mean is, we need a simpler solution."},"a6":{"d":1,"phrase":"It depends on...","pt":"Depende de...","when":"quando a resposta varia conforme a condição","ex":"It depends on the requirements."},"a7":{"d":1,"phrase":"I'd rather... than...","pt":"Eu preferiria... a...","when":"ao comparar preferências","ex":"I'd rather use Go than maintain a larger runtime."},"b1":{"d":2,"phrase":"It turns out that...","pt":"Acontece que...","when":"ao relatar uma descoberta inesperada","ex":"It turns out that the bug was in the cache."},"b2":{"d":2,"phrase":"I'm used to...","pt":"Estou acostumado a...","when":"ao falar do que já é familiar","ex":"I'm used to working remotely."},"b3":{"d":2,"phrase":"I'd like to make sure...","pt":"Quero me certificar de que...","when":"ao confirmar algo com educação","ex":"I'd like to make sure we agree on the scope."},"c1":{"d":3,"phrase":"I'm trying to figure out...","pt":"Estou tentando entender...","when":"ao investigar algo incerto","ex":"I'm trying to figure out why it failed."},"c2":{"d":3,"phrase":"Could you walk me through...?","pt":"Pode me explicar passo a passo?","when":"ao pedir uma explicação guiada","ex":"Could you walk me through the process?"},"c3":{"d":3,"phrase":"As far as I know,...","pt":"Pelo que eu sei,...","when":"ao sinalizar conhecimento ainda não confirmado","ex":"As far as I know, the meeting is online."},"d1":{"d":4,"phrase":"Could we go over...?","pt":"Podemos revisar...?","when":"ao alinhar detalhes","ex":"Could we go over the API requirements?"},"d2":{"d":4,"phrase":"The main trade-off is...","pt":"O principal dilema é...","when":"ao comparar ganhos e perdas","ex":"The main trade-off is cost versus availability."},"d3":{"d":4,"phrase":"That being said,...","pt":"Dito isso,...","when":"ao apresentar uma ressalva","ex":"That being said, we should test the simpler option."},"e1":{"d":5,"phrase":"I'd go with... because...","pt":"Eu escolheria... porque...","when":"ao recomendar uma alternativa","ex":"I'd go with ECS because the load is predictable."},"e2":{"d":5,"phrase":"We need to account for...","pt":"Precisamos levar em conta...","when":"ao considerar custos ou riscos","ex":"We need to account for database connections."},"e3":{"d":5,"phrase":"What I'm getting at is...","pt":"O que quero dizer é...","when":"ao explicar melhor seu ponto","ex":"What I'm getting at is, a rewrite needs a benefit."},"f1":{"d":6,"phrase":"I was wondering if...","pt":"Queria saber se...","when":"ao fazer um pedido delicado","ex":"I was wondering if you had a minute."},"f2":{"d":6,"phrase":"Just to clarify,...","pt":"Só para esclarecer,...","when":"ao confirmar um detalhe","ex":"Just to clarify, is the deadline Friday?"},"f3":{"d":6,"phrase":"I'll get back to you.","pt":"Depois te dou um retorno.","when":"quando precisa verificar antes de responder","ex":"I'll get back to you after checking."},"g1":{"d":7,"phrase":"Would you mind + -ing...?","pt":"Você se importaria de...?","when":"ao pedir ajuda com educação","ex":"Would you mind checking the logs?"},"h1":{"d":8,"phrase":"What I'd suggest is...","pt":"O que eu sugiro é...","when":"ao recomendar uma solução","ex":"What I'd suggest is checking the logs first."},"h2":{"d":8,"phrase":"We ran into...","pt":"Nos deparamos com...","when":"ao relatar um imprevisto","ex":"We ran into an issue during testing."},"h3":{"d":8,"phrase":"From my perspective,...","pt":"Do meu ponto de vista,...","when":"ao apresentar sua opinião","ex":"From my perspective, reliability comes first."},"i1":{"d":9,"phrase":"I'm leaning towards...","pt":"Estou inclinado a...","when":"ao preferir algo sem decidir","ex":"I'm leaning towards a smaller flat."},"i2":{"d":9,"phrase":"The tricky part is...","pt":"O complicado é...","when":"ao apontar a maior dificuldade","ex":"The tricky part is handling retries safely."},"i3":{"d":9,"phrase":"Could you give me a heads-up?","pt":"Pode me avisar antes?","when":"ao pedir aviso antecipado","ex":"Give me a heads-up if the schedule changes."},"j1":{"d":10,"phrase":"I'm not sure whether...","pt":"Não sei ao certo se...","when":"quando há dúvida entre possibilidades","ex":"I'm not sure whether the bus runs on Sunday."},"j2":{"d":10,"phrase":"As soon as...","pt":"Assim que...","when":"ao prometer agir depois de algo","ex":"As soon as I hear back, I'll let you know."},"j3":{"d":10,"phrase":"I'd appreciate it if...","pt":"Eu agradeceria se...","when":"ao fazer um pedido educado","ex":"I'd appreciate it if you could confirm the time.","meaning":"Make a polite request, usually followed by could or would.","pattern":"I'd appreciate it if + subject + could / would + verb","everyday":"I'd appreciate it if you could text me the address.","tech":"I'd appreciate it if you could confirm the deployment window.","trap":"Avoid 'I'd appreciate if' without 'it'."},"k1":{"d":11,"phrase":"I'm happy to...","pt":"Fico feliz em...","when":"ao oferecer ajuda","ex":"I'm happy to help with the move."},"k2":{"d":11,"phrase":"I ended up + -ing","pt":"Acabei...","when":"ao relatar um resultado inesperado","ex":"I ended up taking the later train."},"k3":{"d":11,"phrase":"On a regular basis","pt":"Regularmente","when":"ao falar de uma rotina recorrente","ex":"We review alerts on a regular basis."},"l1":{"d":12,"phrase":"It slipped my mind.","pt":"Acabei esquecendo.","when":"ao admitir um esquecimento","ex":"Sorry, the appointment slipped my mind."},"l2":{"d":12,"phrase":"Make the most of...","pt":"Aproveitar ao máximo...","when":"ao aproveitar bem uma oportunidade","ex":"I want to make the most of my study time."},"m1":{"d":13,"phrase":"I'm due to...","pt":"Tenho previsão de...","when":"ao falar de algo agendado","ex":"I'm due to start a new role next month."},"m2":{"d":13,"phrase":"Keep an eye on...","pt":"Ficar de olho em...","when":"ao acompanhar algo que pode mudar","ex":"Keep an eye on the API error rate."},"m3":{"d":13,"phrase":"Every now and then","pt":"De vez em quando","when":"ao mencionar um hábito ocasional","ex":"I work from a café every now and then."},"n1":{"d":14,"phrase":"I'm on track to...","pt":"Estou no caminho para...","when":"ao relatar progresso dentro do prazo","ex":"I'm on track to finish the migration by Friday."},"n2":{"d":14,"phrase":"I'm running behind","pt":"Estou atrasado","when":"ao avisar atraso numa tarefa","ex":"Sorry, I'm running behind this morning."},"n3":{"d":14,"phrase":"Set aside time for...","pt":"Reservar tempo para...","when":"ao proteger um horário na agenda","ex":"I set aside time for English practice.","meaning":"Reserve a specific period for an activity.","pattern":"set aside + time / a period + for + noun / -ing","everyday":"I set aside an hour for reading.","tech":"I set aside time for incident reviews.","trap":"Use 'for' before the activity."},"o1":{"d":15,"phrase":"What stood out to me was...","pt":"O que mais me chamou atenção foi...","when":"ao destacar algo marcante","ex":"What stood out to me was the team's response."},"o2":{"d":15,"phrase":"I took ownership of...","pt":"Assumi a responsabilidade por...","when":"ao explicar sua contribuição","ex":"I took ownership of the API rollout."},"o3":{"d":15,"phrase":"Looking back, I would...","pt":"Olhando para trás, eu teria...","when":"ao refletir sobre o que faria diferente","ex":"Looking back, I would involve QA earlier."},"p1":{"d":16,"phrase":"I'm in the middle of...","pt":"Estou no meio de...","when":"quando está ocupado fazendo algo","ex":"I'm in the middle of a deployment.","meaning":"I am currently occupied with an activity.","pattern":"I'm in the middle of + noun / -ing","everyday":"I'm in the middle of preparing dinner.","tech":"I'm in the middle of reviewing the deployment.","trap":"Use -ing after 'of': in the middle of working."},"p2":{"d":16,"phrase":"That works for me.","pt":"Por mim, está ótimo.","when":"quando aceita uma proposta","ex":"Tuesday at ten? That works for me."},"p3":{"d":16,"phrase":"We should rule out...","pt":"Precisamos descartar...","when":"ao investigar uma causa possível","ex":"We should rule out a network issue."},"q1":{"d":17,"phrase":"I can fit ... in","pt":"Consigo encaixar ... na agenda","when":"ao encontrar um horário para uma tarefa ou compromisso","meaning":"I have enough room in my schedule for something.","pattern":"I can fit + activity / appointment + in + time expression","everyday":"I can fit a grocery run in before dinner.","tech":"I can fit a quick code review in after stand-up.","trap":"Fit in means make time for something here, not physically fit inside.","ex":"I can fit a quick call in after lunch."},"q2":{"d":17,"phrase":"I haven't got around to ... yet","pt":"Ainda não consegui parar para fazer ...","when":"ao explicar que uma tarefa continua pendente sem prometer uma data","meaning":"I have not found the time or opportunity to do it.","pattern":"I haven't got around to + noun / -ing + yet","everyday":"I haven't got around to unpacking the last box yet.","tech":"I haven't got around to reviewing the logs yet.","trap":"Use an -ing verb after 'to' here: got around to checking, not got around to check.","ex":"I haven't got around to booking the appointment yet."},"q3":{"d":17,"phrase":"Could we push ... back to ...?","pt":"Podemos adiar ... para ...?","when":"ao negociar um novo horário de forma educada","meaning":"Ask politely to move an appointment or deadline to a later time.","pattern":"Could we push + event + back to + later time?","everyday":"Could we push our coffee catch-up back to Saturday?","tech":"Could we push the design review back to 3 p.m.?","trap":"Push back normally means later; bring forward means earlier.","ex":"Could we push the call back to Thursday?"},"r1":{"d":18,"phrase":"The key constraint is...","pt":"A principal restrição é... ","when":"ao destacar a limitação mais importante de um problema","meaning":"The most important limitation we must respect.","pattern":"The key constraint is + noun phrase / that-clause","everyday":"The key constraint is our travel budget.","tech":"The key constraint is that the service must remain available during migration.","trap":"Constraint means a limit or requirement, not necessarily a complaint.","ex":"The key constraint is the deadline."},"r2":{"d":18,"phrase":"I'd break ... down into ...","pt":"Eu dividiria ... em ...","when":"ao explicar um problema complexo em etapas simples","meaning":"I would divide a complex topic into manageable parts.","pattern":"I'd break + problem/task + down into + parts/stages","everyday":"I'd break the moving plan down into three stages.","tech":"I'd break the system design down into storage, processing and reliability.","trap":"Break down can mean stop working in other contexts; here it means divide for analysis.","ex":"I'd break the problem down into three parts."},"r3":{"d":18,"phrase":"To put that into perspective,...","pt":"Para dar uma ideia da proporção,...","when":"ao contextualizar um número ou comparação","meaning":"To help someone understand the scale or significance of a fact.","pattern":"To put that into perspective, + meaningful comparison","everyday":"To put that into perspective, the train ride takes twice as long as the drive.","tech":"To put that into perspective, doubling traffic from 5,000 to 10,000 requests a minute changes our capacity target.","trap":"Provide a relevant, accurate comparison; do not invent measured results.","ex":"To put that into perspective, the queue could double in size."},"s1":{"d":19,"phrase":"Are we on the same page about...?","pt":"Estamos alinhados sobre...?","when":"ao confirmar se todos entenderam o mesmo objetivo ou decisão","meaning":"Ask whether people share the same understanding.","pattern":"Are we on the same page about + noun / -ing?","everyday":"Are we on the same page about meeting at the station?","tech":"Are we on the same page about the rollback criteria?","trap":"This is figurative: no physical page is involved.","ex":"Are we on the same page about the release plan?"},"s2":{"d":19,"phrase":"Let's get to the root of...","pt":"Vamos chegar à causa principal de...","when":"ao propor investigar a origem de um problema, não apenas seus sintomas","meaning":"Suggest finding the underlying cause rather than treating symptoms.","pattern":"Let's get to the root of + problem / issue","everyday":"Let's get to the root of why the heating keeps stopping.","tech":"Let's get to the root of the repeated timeout errors.","trap":"Root is figurative here; it is not a tree root.","ex":"Let's get to the root of the latency issue."},"s3":{"d":19,"phrase":"This is grounded in...","pt":"Isso se fundamenta em...","when":"ao justificar uma conclusão com evidências ou informações verificáveis","meaning":"Say that a claim or decision has a solid basis in evidence.","pattern":"This is grounded in + evidence / observations / data","everyday":"This advice is grounded in the timetable we checked.","tech":"This recommendation is grounded in the current error metrics.","trap":"Grounded is figurative here; it does not mean physically touching the ground.","ex":"This proposal is grounded in the available evidence."},"t1":{"d":20,"phrase":"I'm up for...","pt":"Topo... / Estou a fim de...","when":"ao aceitar ou mostrar interesse por um convite informal","meaning":"I am willing or interested in doing something.","pattern":"I'm up for + noun / -ing","everyday":"I'm up for a walk after lunch.","tech":"I'm up for a short design discussion after stand-up.","trap":"Use -ing after 'for': up for trying, not up for try.","ex":"I'm up for trying that new café."},"t2":{"d":20,"phrase":"How about we...?","pt":"Que tal a gente...?","when":"ao sugerir um plano de forma casual e colaborativa","meaning":"Suggest an activity to do together.","pattern":"How about we + base verb?","everyday":"How about we meet at the library?","tech":"How about we review the API contract tomorrow?","trap":"After 'we', use the base verb: How about we meet? Compare 'How about meeting?'.","ex":"How about we take the earlier train?"},"t3":{"d":20,"phrase":"I'll play it by ear.","pt":"Vou decidir na hora / conforme a situação.","when":"quando prefere decidir os detalhes depois, dependendo de como as coisas acontecerem","meaning":"Decide later depending on circumstances.","pattern":"I'll play it by ear + optional context.","everyday":"I haven't planned Sunday yet; I'll play it by ear.","tech":"If the demo ends early, I'll play it by ear before scheduling another call.","trap":"Figurative expression: it is not about playing music literally.","ex":"I haven't decided what to do after lunch; I'll play it by ear."},"u1":{"d":21,"phrase":"I'm looking forward to...","pt":"Estou ansioso para... / Estou na expectativa de...","when":"ao demonstrar expectativa positiva sobre um encontro ou evento","meaning":"Express positive anticipation of something in the future.","pattern":"look forward to + noun / -ing","everyday":"I'm looking forward to visiting the library.","tech":"I'm looking forward to reviewing the prototype.","trap":"The 'to' is a preposition: use -ing, not an infinitive.","ex":"I'm looking forward to seeing the exhibition."},"u2":{"d":21,"phrase":"It caught my eye.","pt":"Chamou minha atenção.","when":"ao comentar algo que percebeu numa vitrine ou anúncio","meaning":"Something visually attracted my attention.","pattern":"something + caught + my/your + eye","everyday":"That blue jacket caught my eye.","tech":"The unusual error pattern caught my eye.","trap":"Not the literal meaning of physically catching an eye.","ex":"The poster caught my eye."},"u3":{"d":21,"phrase":"Do you happen to know...?","pt":"Por acaso você sabe...?","when":"ao pedir uma informação sem pressupor que a pessoa saiba","meaning":"Ask for information politely and without assuming the listener knows.","pattern":"Do you happen to know + noun / if / where + subject + verb","everyday":"Do you happen to know when the museum closes?","tech":"Do you happen to know whether the staging build is ready?","trap":"Use statement order after 'know': where the museum is, not where is the museum.","ex":"Do you happen to know where the nearest pharmacy is?"}},"F":{"spelling":{"title":"Letters and spelling","rule":"Say the letter name, not its sound inside a word. Spell names, abbreviations and emails slowly.","qs":["Spell API aloud.","Spell AWS aloud.","Spell IAM aloud.","Spell KMS aloud.","Say the letter G.","Say the letter J.","Say the letter W.","Spell your email address aloud."],"ans":["A-P-I","A-W-S","I-A-M","K-M-S","/dʒiː/","/dʒeɪ/","double-u","Say each letter, then 'at', 'dot' and the domain."]},"numbers":{"title":"Numbers and quantities","rule":"Group digits naturally; read 1.2 million as 'one point two million'. Practise the whole number, not separate digits.","qs":["105","1,250","48,600","2.4 million","750,000","3 billion","12,500","18.5%"],"ans":["one hundred and five","one thousand two hundred and fifty","forty-eight thousand six hundred","two point four million","seven hundred and fifty thousand","three billion","twelve thousand five hundred","eighteen point five percent"]},"money":{"title":"Money and percentages","rule":"Say the currency and decimals naturally: €2.50 = two euros fifty. Percent uses 'percent', not 'per cents'.","qs":["€2.50","€89.90","€1,350","€2,300","€96,000","4.5%","125,000","1.2 million"],"ans":["two euros fifty","eighty-nine euros ninety","one thousand three hundred and fifty euros","two thousand three hundred euros","ninety-six thousand euros","four point five percent","one hundred and twenty-five thousand","one point two million"]},"times":{"title":"Dates, times and deadlines","rule":"Use on + weekday/date; at + time; in + month/year; by + deadline; until + continuation.","qs":["___ Monday","___ 9 a.m.","___ November","Finish ___ Friday","Continue working ___ Friday","___ 2027","___ noon","___ 11 November"],"ans":["on","at","in","by","until","in","at","on"]},"preps":{"title":"Useful prepositions","rule":"Since + starting point; for + duration; at + time; on + day; in + year/place; to + destination; depend on.","qs":["___ 2021","___ three years","___ Monday","___ 8:30","___ November","go ___ the office","depend ___ traffic","arrive ___ Dublin"],"ans":["since","for","on","at","in","to","on","in"]},"questions":{"title":"Natural question structure","rule":"Direct: auxiliary + subject + base verb. Indirect: Could you tell me where it runs? (statement order).","qs":["Where ___ you work?","When ___ it fail yesterday?","How long ___ you worked with AWS?","What ___ this endpoint return?","___ you available tomorrow?","Why ___ she choose Go?","How often ___ the team deploy?","What time ___ it start yesterday?"],"ans":["do","did","have","does","Are","did","does","did"]}},"days":[{"day":1,"theme":"From understanding to speaking","micro":"spelling","small":"Introduce yourself to an international team.","scenario":"Explain your experience with backend systems and why you might choose Go and Cobra for a CLI.","writing":"Write about your career and goals.","chunks":["a1","a2","a3","a4","a5","a6","a7"],"note":"","date":"2026-10-29","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"interview"},{"day":2,"theme":"Numbers & natural explanations","micro":"numbers","small":"Discuss estimated living costs while preparing to move abroad.","scenario":"Simulated: an API handles 12,500 requests/minute and traffic may double. Explain what you would measure.","writing":"Write a short technical estimate with an uncertainty.","chunks":["b1","b2","b3","a1","a3","a6"],"note":"","date":"2026-10-30","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":3,"theme":"Clarify, investigate, explain","micro":"preps","small":"At a flat viewing, what would you check before paying a deposit?","scenario":"Simulated: a payment API times out intermittently. Explain your first checks.","writing":"Clarify requirements and next steps in a work message.","chunks":["c1","c2","c3","b1","b2","b3"],"note":"","date":"2026-10-31","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":4,"theme":"Clear decisions & trade-offs","micro":"times","small":"Explain your weekend plans and what has changed.","scenario":"Simulated: compare two backend architectures with different cost and reliability requirements.","writing":"Write a recommendation with one clear trade-off.","chunks":["d1","d2","d3","a6","c2","c3"],"note":"","date":"2026-11-01","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":5,"theme":"Ask better questions","micro":"questions","small":"Ask a new neighbour about the local area.","scenario":"Explain why you would choose one cloud option over another.","writing":"Write a message asking for a decision and explaining a recommendation.","chunks":["e1","e2","e3","d1","d2","b2"],"note":"","date":"2026-11-02","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":6,"theme":"Everyday reflexes & clear updates","micro":"numbers","small":"Meet a new neighbour and introduce yourself politely.","scenario":"A colleague asks about an API delay. What is confirmed and what is pending?","writing":"Write an update, ask one question and promise a follow-up.","chunks":["f1","f2","f3","e1","e2","c2"],"note":"","date":"2026-11-03","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":7,"theme":"Clear decisions & polite requests","micro":"questions","small":"A new colleague asks about your weekend.","scenario":"Simulated: choose a queue or synchronous calls for an API.","writing":"Write a polite clarification and next step.","chunks":["a6","c3","g1","f1","f2","f3"],"note":"Original Day 7 incorrectly marked two previously introduced chunks NEW; corrected here.","date":"2026-11-04","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":8,"theme":"Diagnose & explain","micro":"questions","small":"How is remote work going? Discuss your plans abroad.","scenario":"Describe a real backend incident without inventing results.","writing":"Write a short incident summary with a finding and next step.","chunks":["h1","h2","h3","d1","f2","b1"],"note":"","date":"2026-11-05","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"interview"},{"day":9,"theme":"Clear choices & everyday numbers","micro":"money","small":"How are you settling in? Discuss transport and shopping.","scenario":"Simulated: compare two APIs with different cost and reliability profiles.","writing":"Write a recommendation using a number and a reason.","chunks":["i1","i2","i3","h1","h2","h3"],"note":"","date":"2026-11-06","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":10,"theme":"Polite requests and plans","micro":"preps","small":"Ask a neighbour about local transport and weekend plans.","scenario":"Simulated: explain a delayed release and request an update.","writing":"Write a polite request to reschedule a meeting.","chunks":["j1","j2","j3","i1","f3","c1"],"note":"","date":"2026-11-07","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":11,"theme":"Everyday ease & technical trade-offs","micro":"questions","small":"A neighbour asks how your weekend went.","scenario":"Simulated: would you introduce a message queue or keep synchronous processing?","writing":"Write a five-sentence message explaining a technical choice.","chunks":["k1","k2","k3","j1","h2","d2"],"note":"","date":"2026-11-08","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":12,"theme":"Plans, decisions & small surprises","micro":"money","small":"A neighbour asks why you chose this neighbourhood.","scenario":"Simulated: choose between two job offers with different salary and commute.","writing":"Write five sentences explaining a decision and alternative.","chunks":["i1","l1","l2","k2","k1","k3"],"note":"Original Day 12 incorrectly marked an earlier Day 9 chunk NEW; corrected here.","date":"2026-11-09","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"everyday"},{"day":13,"theme":"Keeping plans on track","micro":"times","small":"A neighbour asks how your week is going.","scenario":"Simulated: API error rates rise after deployment. What would you check first?","writing":"Write a deployment update with monitoring steps.","chunks":["m1","m2","m3","l1","l2","j3"],"note":"","date":"2026-11-10","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":14,"theme":"Clear updates & commitments","micro":"preps","small":"A neighbour asks whether you've settled into your routine.","scenario":"Simulated: a release may miss Friday's deadline. Give an honest update.","writing":"Write a five-sentence delayed-release update.","chunks":["n1","n2","n3","m1","m2","f2"],"note":"","date":"2026-11-11","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":15,"theme":"Owning your story","micro":"questions","small":"A teammate asks how your week has been.","scenario":"Behavioural interview: Tell me about a time you took ownership of a difficult problem.","writing":"Write about one real technical decision, using only verified results.","chunks":["o1","o2","o3","n1","k2","c2"],"note":"","date":"2026-11-12","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"interview"},{"day":16,"theme":"Keep the conversation moving","micro":"questions","small":"A new colleague asks how your first week is going.","scenario":"Simulated: an API gets slower after a release. Explain your first checks.","writing":"Write 2–4 sentences about the incident and rewrite one using a chunk.","chunks":["p1","p2","p3","o1","n3","h2"],"note":"","date":"2026-11-13","source":"HTML adaptation from the original archived PDF worksheet","scenario_type":"workplace"},{"day":17,"theme":"Making time when plans change","micro":"spelling","small":"You're meeting a neighbour at a community event. They ask what you've been doing this weekend. Talk about one plan, one unfinished task and one change of schedule.","scenario":"Role-play: you have a flat-viewing appointment and a separate 20-minute team call on the same afternoon. A new time conflict appears. Explain your priorities, propose a practical alternative and ask for confirmation. The AI partner should play the other person and reveal the conflict only after your first answer.","writing":"Write a short message to reschedule an appointment. Explain the conflict briefly, offer one alternative, and ask for confirmation. Then rewrite one sentence using a target chunk.","chunks":["q1","q2","q3","p1","n3","j3"],"note":"First published as a native interactive HTML lesson. Review spacing: Day 16 (1 day), Day 14 (3 days), Day 10 (7 days).","date":"2026-11-14","source":"Native interactive HTML lesson","noticing":"On Saturday morning, I told a neighbour that I could fit a short coffee break in before lunch. I hadn't got around to finishing a few household tasks yet, and I was in the middle of sorting them out. Later, a colleague asked to change our call. I said, “Could we push the call back to 4 p.m.?” I had set aside time for it, so I added, “I'd appreciate it if you could confirm the new time.”","story":"Tell a true 3–5-sentence story about a day when you had several things to do. Use at least two of today's chunks, but only where they fit naturally. If the story is hypothetical, clearly say so.","recovery":"Start a sentence about a missed appointment. Halfway through, pretend you have forgotten the word for 'reschedule'. Keep talking: 'What I mean is, could we meet later instead?' Then try again with a different missing word. Do not restart the whole sentence.","soloQuestions":["At a community event, how would you explain what you have planned for the weekend?","You have two commitments at the same time. How would you decide what to move, and what would you say to the other person?","What unfinished task have you been meaning to do, and when could you fit it in?"],"writingCheck":"Check whether 'got around to' is followed by a noun or an -ing verb, whether 'push back' refers to a later time, and whether your request gives a clear alternative. Example structure (reveal after trying): 'Could we push our appointment back to Thursday? I can fit it in after lunch. I'd appreciate it if you could confirm.'","foundationExtra":"Spelling practice: say letter names clearly, pause between groups, and practise B/V, G/J, E/I, and M/N contrasts. Never share a real password or private email address in public practice.","scenario_type":"everyday"},{"day":18,"date":"2026-11-15","theme":"Explain constraints and scale clearly","micro":"numbers","scenario_type":"interview","small":"At a casual lunch, someone asks what kind of food you enjoy cooking. Give one honest preference, one detail, and optionally ask what they like. If you do not cook much, say so naturally.","scenario":"Technical system-design interview: design an order-processing API for a hypothetical online shop. The interviewer first asks what you need to clarify. Then explain your key constraint, break the design into components, and reason about a hypothetical rise from 5,000 to 10,000 requests per minute. Discuss reliability, asynchronous processing, failure handling, and one trade-off. Ask one clarification question before proposing a design. Never claim that these figures come from a real system.","writing":"Write 2–4 sentences about the hypothetical order-processing design: state one constraint, explain two components, and contextualize the traffic increase. Rewrite one sentence with a target chunk. If time remains, extend to 4–8 sentences and rewrite a second one.","chunks":["r1","r2","r3","q1","o1","k2"],"source":"Native interactive HTML lesson","note":"Spaced review: Day 17 (1 day), Day 15 (3 days), Day 11 (7 days). Day 18 starts the daily context-clue practice. Technical interview numbers are hypothetical.","noticing":"During a mock design interview, I said, 'The key constraint is keeping orders reliable during traffic spikes.' I'd break the problem down into API validation, message handling and persistence. To put that into perspective, moving from 5,000 to 10,000 requests a minute means planning for twice the incoming rate. I can fit a short explanation in before discussing alternatives. What stood out to me was the need for clear failure handling. I ended up recommending an asynchronous step in this hypothetical example, but only after stating the assumptions.","story":"Describe a hypothetical app you use or would like to build. In 3–5 sentences, name the key constraint and break the problem down into smaller parts. Use at least two target chunks, and clearly label invented numbers as assumptions.","recovery":"Start explaining a design. Pretend you cannot remember the word 'throughput'. Keep speaking: 'What I mean is, how many requests the system handles each minute.' Repeat with 'latency' (how long one request takes). Keep the sentence moving instead of restarting.","soloQuestions":["At a casual lunch, what food do you enjoy making or eating, and why?","For a hypothetical order API, what question would you ask before choosing the architecture, and what is the key constraint?","If incoming traffic doubled from 5,000 to 10,000 requests per minute, how would you break the design down and explain the scale without inventing measured results?"],"writingCheck":"Check that 'The key constraint is' introduces a real limitation, that 'break ... down into' names meaningful parts, and that your comparison uses the same unit. Model after trying: 'The key constraint is reliable order processing. I'd break the design down into validation, messaging and storage. To put that into perspective, 10,000 requests per minute is twice a hypothetical baseline of 5,000.'","foundationExtra":"Read the figures aloud: 5,000 = five thousand; 10,000 = ten thousand; 125,000 = one hundred and twenty-five thousand; 1,250,000 = one million two hundred and fifty thousand. In technical speech, say the unit clearly: requests per minute, milliseconds, or percent.","ambiguity":{"sentence":"During the design review, the engineer said the queue was a bottleneck because messages arrived faster than consumers could process them.","expression":"bottleneck","gist_question":"What is limiting the system's ability to process incoming messages?","plain_english":"A part of a process that slows down the whole system.","context_clue":"The phrase 'messages arrived faster than consumers could process them' points to a processing limit; the sentence does not identify its exact cause.","gist_answer":"The queue-processing stage is the limiting part; more messages are arriving than consumers can handle."}},{"day":19,"date":"2026-11-16","theme":"Metaphors and meaning in everyday and technical English","micro":"preps","scenario_type":"workplace","small":"At a café, someone unexpectedly asks whether you prefer visiting a new place alone or with company. Give a truthful short answer, add one detail, and optionally ask what they prefer. If you have no preference, say so. Then switch to quick unrelated questions about a meal, a hobby and a free afternoon.","scenario":"Workplace role-play: a hypothetical team is investigating intermittent timeouts in an API after a release. A teammate says 'the queue is a bottleneck' and asks whether everyone is on the same page about the evidence. First distinguish observed facts from guesses, clarify what the figurative expressions mean, and propose a safe investigation using logs, traces and metrics. Ask one clarification question, explain a possible root cause without claiming it is proven, discuss rollback criteria and agree on a next step. The AI partner reveals additional hypothetical evidence only after the learner responds.","writing":"Write 2–4 sentences to a teammate about the hypothetical timeout investigation. Distinguish an observation from a hypothesis, use one target chunk, and suggest a next step. Rewrite one sentence to make it more natural. Optional: expand to 4–8 sentences and rewrite a second sentence within the same ten minutes.","chunks":["s1","s2","s3","r1","p1","l2"],"source":"Native interactive HTML lesson","note":"Focused metaphor lesson: literal versus figurative meaning, context clues and cautious inference. Spaced review from Days 18 (1 day), 16 (3 days) and 12 (7 days). All system incidents are hypothetical; do not infer learner performance.","noticing":"Literal language describes a physical situation: a tree has roots, a book has pages, and a bottle has a narrow neck. Figurative language uses those familiar words to express abstract ideas. In a hypothetical API review, a teammate says, 'Are we on the same page about the incident?' The engineer replies, 'Let's get to the root of the issue; this hypothesis is grounded in the traces we collected.' Here, same page means shared understanding, root means underlying cause, and grounded means supported by evidence. A bottleneck is a limiting stage, not necessarily a physical bottle. Under the hood means inside a system. Do not mistake a metaphor for a verified diagnosis: ask for evidence if the technical decision depends on it. The key constraint is safe operation. I'm in the middle of checking the traces, and I want to make the most of the evidence available.","story":"In a 3–5-sentence hypothetical workplace story, describe a team disagreement about an API timeout. Use at least two of today's chunks to align understanding and propose an evidence-based investigation. Do not claim the scenario happened to you.","recovery":"Halfway through explaining a timeout, pretend you forget the word 'bottleneck'. Continue without restarting: 'What I mean is, one stage is slowing the whole process down.' Repeat for 'grounded in' using 'supported by the information we have' and for 'root cause' using 'the underlying reason'.","soloQuestions":["At a café, do you prefer exploring a new place alone or with someone? Give a truthful answer and one detail.","In a hypothetical API incident, what would you say to confirm the team agrees on the observed facts?","How would you investigate intermittent timeouts, distinguish a metaphorical 'bottleneck' from evidence, and explain the next safe step?"],"writingCheck":"After trying, compare with this hypothetical model: 'We observed intermittent timeouts after the release, but the cause is not confirmed. Are we on the same page about the current evidence? Let's get to the root of the issue by checking traces and queue metrics. Our next decision should be grounded in the results.' Check 'about' after 'same page', 'of' after 'root', and 'in' after 'grounded'.","foundationExtra":"Today, contrast literal and figurative meaning while practising prepositions: on the same page (about a decision), at the root of the issue, under the hood, grounded in evidence. The words page, root, hood and ground have physical meanings; in these expressions they carry figurative meanings. A metaphor is a comparison without necessarily using 'like'. Context clues suggest meaning, but critical technical decisions still require confirmation. Use the existing eight preposition questions and ten everyday reflex cues within the 15-minute block.","ambiguity":{"sentence":"The team said the rollback decision should be grounded in the latest traces rather than a hunch.","expression":"grounded in","gist_question":"What should the team use to decide whether to roll back?","plain_english":"Supported by evidence or reliable information.","context_clue":"The contrast between 'latest traces' and 'a hunch' suggests evidence rather than intuition; the traces still need interpretation.","gist_answer":"They should base the decision on the latest trace evidence, not merely on a guess."}},{"day":20,"date":"2026-11-17","theme":"Making casual plans without overthinking","micro":"times","scenario_type":"everyday","small":"At a bus stop, a stranger asks what you usually do when you have an unexpected free hour. Give a truthful short answer, one detail and an optional return question. Then switch rapidly to questions about a favourite snack, a recent film and a rainy afternoon. It is fine to say you have not decided.","scenario":"Everyday role-play: a new acquaintance invites you to a free local weekend event. You have not checked the weather or transport yet. Respond naturally, ask about the meeting place and time, suggest an alternative if the first option is inconvenient, and leave one decision open without making a false promise. The partner should introduce a small unexpected change only after the first learner answer.","writing":"Write 2–4 sentences replying to an informal invitation. State whether you are interested, suggest one practical time or place, and mention one detail you will decide later. Rewrite one sentence with a target chunk. Optional extension within the same ten minutes: expand to 4–8 sentences and rewrite a second sentence.","chunks":["t1","t2","t3","s1","q1","m3"],"source":"Native interactive HTML lesson","note":"Everyday scenario; spaced reviews Day 19 (1 day), Day 17 (3 days), Day 13 (7 days). No invented learner activity or performance.","noticing":"A friend invited me to a free outdoor event this weekend. I said, 'I'm up for it, but I haven't checked the weather yet.' Then I asked, 'How about we meet near the station at eleven?' We agreed on the meeting point, but I didn't choose what to do afterwards. I'll play it by ear. Before leaving, I asked, 'Are we on the same page about the time?' I can fit a short stop at the shop in beforehand. Every now and then, an unplanned afternoon turns into a good one. Notice that 'play it by ear' is figurative: the speaker plans to decide later based on circumstances, not play an instrument.","story":"Tell a short, truthful or clearly hypothetical story about accepting or declining an invitation. Use at least two target chunks and explain one practical constraint without inventing personal plans.","recovery":"Halfway through suggesting an outing, pretend you forget the word 'venue'. Continue without restarting: 'What I mean is, the place where the event happens.' Then paraphrase 'flexible' as 'we can decide later' and 'postpone' as 'move it to another day'.","soloQuestions":["Someone asks what you like to do with a surprise free hour. What is your honest answer, one detail, and a question back?","A new acquaintance invites you to a free Saturday event. Are you up for it, and what would you need to know?","The meeting time changes from eleven to one. Suggest a new plan, confirm understanding, and explain what you will decide on the day."],"writingCheck":"After writing, compare with this model for a hypothetical invitation: 'I'm up for the free event on Saturday. How about we meet near the station at eleven? I'm not sure what I'll do afterwards, so I'll play it by ear. Could you confirm the meeting point?' Check 'up for + noun/-ing', 'How about we + base verb' and the natural figurative expression 'play it by ear'.","foundationExtra":"Practise clock times, prepositions and flexible plans: at eleven, on Saturday, in the afternoon, from ten to noon, half past six, a quarter to eight. Say the time out loud before checking each answer. The ten everyday reflex cues are part of these fifteen minutes, not extra homework.","ambiguity":{"sentence":"We haven't chosen a café yet, so we'll play it by ear depending on the weather and how busy the area is.","expression":"play it by ear","gist_question":"Have they already decided which café to visit?","plain_english":"Decide later using the situation at the time.","context_clue":"'Haven't chosen' and 'depending on the weather' indicate the plan is still flexible.","gist_answer":"No. They will choose later based on conditions."}},{"day":21,"date":"2026-11-18","theme":"Asking for help while exploring a new place","micro":"questions","scenario_type":"everyday","small":"At a shared table, someone unexpectedly asks what kind of place you would visit if you had a completely free afternoon. Give an honest answer, one reason and an optional question back. Then answer three unrelated quick questions about music, a recent purchase and a favourite drink; no invented plans are needed.","scenario":"Everyday role-play: you are visiting a fictional town for the first time and notice a poster for a small exhibition. Ask a local person for the opening hours, clarify whether tickets are required, explain what caught your eye, and say what you are looking forward to. After your first response, the partner introduces an unexpected change: the exhibition is fully booked this afternoon. Ask for a practical alternative without assuming facts or inventing actual opening hours.","writing":"Write 2–4 sentences to a friend about a hypothetical exhibition you noticed: what caught your eye, one polite question you asked, and what you look forward to. Rewrite one sentence using a target chunk. If time remains, extend to 4–8 sentences and rewrite a second sentence. Compare with the model only after attempting.","chunks":["u1","u2","u3","t1","r2","n3"],"source":"Native interactive HTML lesson","note":"Everyday scenario with 1-, 3-, and 7-day verified reviews from Days 20, 18 and 14. Day 21 weekly checkpoint: assess recognition versus spontaneous use only from actual learner attempts, without invented scores.","noticing":"I was exploring a new town when a colourful poster caught my eye. I'm looking forward to seeing the exhibition, but I don't know the opening hours. I asked a passer-by, 'Do you happen to know when it closes?' They weren't sure, so I checked the venue's official notice instead. I'm up for visiting tomorrow if tickets are available. I'd break the visit down into a short exhibition and a walk. I set aside time for the trip, but I won't make assumptions about opening hours.","story":"Describe a real or explicitly imagined place you would like to explore. Explain what caught your eye, ask a polite question, and use at least two target chunks. If you have no particular destination in mind, choose a category such as a park, market or museum.","recovery":"Pretend you forget the word 'exhibition' halfway through a sentence. Continue: 'What I mean is, the display of art or objects at the museum.' Next forget 'fully booked' and paraphrase 'there are no tickets left'. Keep talking without restarting.","soloQuestions":["What kind of place would you visit with a free afternoon, and why? Give a truthful answer and a return question.","You see a poster for a small exhibition. What catches your eye, and how would you ask a stranger about the opening hours?","The exhibition is fully booked today. Ask about another date and explain what you are looking forward to without assuming the answer."],"writingCheck":"After attempting, compare with this fictional example: 'A colourful exhibition poster caught my eye. Do you happen to know when the museum opens? I'm looking forward to seeing the display, but I need to check whether tickets are available.' Check 'look forward to seeing', indirect question order 'when the museum opens', and the past tense 'caught'.","foundationExtra":"Practise direct versus indirect questions: 'Where is the gallery?' becomes 'Do you happen to know where the gallery is?' and 'When does it close?' becomes 'Do you happen to know when it closes?' The eight question exercises and ten quick everyday reflexes fit within the 15-minute foundations block.","ambiguity":{"sentence":"A bright poster caught my eye as I walked past the gallery, so I stopped to read it.","expression":"caught my eye","gist_question":"Why did the speaker stop near the gallery?","plain_english":"Attracted my attention, especially visually.","context_clue":"The poster was bright and the speaker stopped to read it; nothing was physically caught.","gist_answer":"The poster attracted the speaker's attention, so they stopped to look at it."}}],"reflexPool":[["Here you go.","Thanks!"],["Thanks for your help.","You're welcome! / No problem."],["Have a lovely weekend!","You too!"],["Sorry I'm late.","No worries."],["Nice to meet you.","Nice to meet you too."],["Could I sit here?","Of course. / Go ahead."],["Would you like a receipt?","No, thanks. / Yes, please."],["Could you pass me that pen?","Sure, here you go."],["Sorry, could I get past?","Of course!"],["Would three o'clock suit you?","Yes, that works for me."],["You're doing a great job.","Thanks, I appreciate that."],["How's your week going?","Pretty well, thanks. How about yours?"]],"focusDrills":{"1":["I tend to check the logs first.",[["the logs","the metrics"],["first","every morning"],["I tend","We tend"],["the metrics","the alerts"]]],"2":["I'm used to working remotely.",[["remotely","with international teams"],["I'm","We're"],["working","collaborating"],["international teams","colleagues abroad"]]],"3":["I'm trying to figure out why the API failed.",[["the API","the deployment"],["failed","slowed down"],["I'm","We're"],["the deployment","the database"]]],"4":["We should go over the plan tomorrow.",[["the plan","the requirements"],["tomorrow","today"],["We","They"],["the requirements","the numbers"]]],"5":["I'd go with Go because it's simpler.",[["Go","Java"],["simpler","faster"],["I'd","We'd"],["Java","Kotlin"]]],"6":["I was wondering if we could talk tomorrow.",[["tomorrow","today"],["talk","meet"],["we","you"],["today","at noon"]]],"7":["Would you mind checking the logs?",[["the logs","the dashboard"],["checking","reviewing"],["the dashboard","the report"],["reviewing","sharing"]]],"8":["We ran into a problem during testing.",[["a problem","a delay"],["testing","deployment"],["We","They"],["a delay","a timeout"]]],"9":["I'm leaning towards renting a small flat.",[["small","larger"],["flat","house"],["I'm","We're"],["renting","buying"]]],"10":["I'm not sure whether the train runs on Sunday.",[["the train","the bus"],["Sunday","Saturday"],["I'm","We're"],["the bus","the service"]]],"11":["I ended up taking the later train.",[["train","bus"],["later","earlier"],["I ended","We ended"],["taking","catching"]]],"12":["It slipped my mind to book the appointment.",[["the appointment","the viewing"],["book","confirm"],["the viewing","the meeting"],["confirm","reschedule"]]],"13":["Keep an eye on the error rate.",[["the error rate","the logs"],["the logs","the response times"],["Keep","Please keep"],["the response times","the queue depth"]]],"14":["I'm on track to finish the report on Friday.",[["the report","the migration"],["Friday","Monday"],["I'm","We're"],["finish","complete"]]],"15":["I took ownership of the deployment.",[["the deployment","the investigation"],["I","We"],["the investigation","the release"],["took","have taken"]]],"16":["I'm in the middle of cooking dinner.",[["cooking dinner","preparing lunch"],["I'm","She's"],["preparing lunch","writing an email"],["She's","They're"],["writing an email","planning a trip"]]],"17":["I can fit a quick call in after lunch.",[["a quick call","a short meeting"],["after lunch","before dinner"],["I can","We can"],["a short meeting","a code review"],["before dinner","on Friday"]]],"18":["I'd break the problem down into three parts.",[["three parts","two stages"],["the problem","the request"],["I'd","We'd"],["two stages","three steps"],["the request","the migration"]]],"19":["Are we on the same page about the release plan?",[["the release plan","the incident timeline"],["Are we","Is the team","Agreement: change the subject and auxiliary together; plural we are → singular team is."],["the incident timeline","the rollback criteria"],["Is the team","Are the engineers","Agreement: singular team is → plural engineers are."],["the rollback criteria","the evidence collected"]]],"20":["I'm up for a walk after lunch.",[["a walk","a short bike ride"],["after lunch","on Saturday"],["I'm","We're"],["a short bike ride","a visit to the museum"],["on Saturday","tomorrow morning"]]],"21":["I'm looking forward to visiting the gallery tomorrow.",[["the gallery","the market"],["tomorrow","on Saturday"],["I'm","We're"],["visiting","exploring"],["the market","the old town"]]]},"av":[["I practise English on weekdays.",[["English","speaking"],["on weekdays","every evening"],["I","We"],["every evening","after work"]]],["We plan a short trip in November.",[["a short trip","a family visit"],["November","December"],["We","They"],["a family visit","a weekend away"]]],["I work from home twice a week.",[["home","the office"],["twice a week","on Fridays"],["I","We"],["the office","a café"]]]],"bv":[["We review the logs before each release.",[["the logs","the metrics"],["each release","deployment"],["We","They"],["before","after"]]],["The team checks latency during an incident.",[["latency","error rates"],["an incident","a deployment"],["The team checks","Our engineers check","Agreement: singular team checks → plural engineers check. Change subject and verb together."],["during","after"]]],["We test the API before deploying.",[["the API","the integration"],["deploying","the release"],["We","They"],["test","review"]]]],"specialDrills16":{"scheduling":["Tuesday at ten works for me.",[["Tuesday","Thursday"],["ten","eleven"],["me","our team"],["Thursday","Friday"],["eleven","nine"]]],"technical":["We should rule out a network issue first.",[["a network issue","a database issue"],["We","The team"],["should","needs to"],["a database issue","a caching problem"],["first","before the release"]]]}};
